"""Run after every release change: python tools/build-pwa.py. No media bulk caching."""
from pathlib import Path
import hashlib,json
root=Path(__file__).resolve().parent.parent
files=[root/'index.html',root/'app.webmanifest']
files+=sorted(x for x in root.iterdir() if x.suffix in ('.js','.css') and x.name!='sw.js' and '.before-' not in x.name)
files+=sorted(x for x in (root/'assets').rglob('*') if x.is_file() and x.suffix in ('.png','.jpg','.webp','.svg') and x.stat().st_size<800000 and 'design-reference' not in x.name)
# Audio is played on demand, never fetched in bulk: download managers may intercept audio precaching.
# Include PNG fallbacks for non-WebP browsers, including the home hero.
files+=sorted(x for x in (root/'assets/home').glob('*.png') if x not in files and 'design-reference' not in x.name)
files+=sorted(x for x in (root/'games/mystery-box').rglob('*') if x.is_file() and x.suffix in ('.html','.png') and x.stat().st_size<500000)
files+=sorted((root/'data').glob('*.json')) if (root/'data').exists() else []
files=list(dict.fromkeys(files))
paths=[x.relative_to(root).as_posix() for x in files]
version=hashlib.sha256(Path(__file__).read_bytes()+b''.join(str(x.relative_to(root)).encode()+x.read_bytes() for x in files)).hexdigest()[:16]
source="""/* Generated by tools/build-pwa.py; progress is stored separately in localStorage. */
'use strict';
var CACHE='lingucat-shell-VERSION';
var SHELL=PATHS;
self.addEventListener('install',function(e){e.waitUntil(caches.open(CACHE).then(function(c){return c.addAll(SHELL).then(function(){return self.skipWaiting();});}).catch(function(err){return caches.delete(CACHE).then(function(){throw err;});}));});
// Activate only after the complete release is cached. Existing progress stays in localStorage.
self.addEventListener('message',function(e){if(e.data&&e.data.type==='ACTIVATE_UPDATE')self.skipWaiting();});
self.addEventListener('activate',function(e){e.waitUntil(self.clients.claim());});
self.addEventListener('fetch',function(e){
 var u=new URL(e.request.url),base=new URL(self.registration.scope);
 if(e.request.method!=='GET'||u.origin!==base.origin||u.pathname.indexOf(base.pathname)!==0)return;
 var path=u.pathname.slice(base.pathname.length);
 // Videos, 3D binaries, remote services always use the network. Small cached audio may return a full 200 response to Range requests.
 if(/\\.(mp4|webm|mov|wasm|pck)$/i.test(path))return;
 if(e.request.mode==='navigate'&&(path===''||path==='index.html')){e.respondWith(caches.open(CACHE).then(function(c){return c.match('index.html').then(function(r){return r||fetch(e.request);});}));return;}
 if(SHELL.indexOf(path)<0)return;
 e.respondWith(caches.open(CACHE).then(function(c){return c.match(path).then(function(r){if(!r)return fetch(e.request);var range=e.request.headers.get('range');if(!range)return r;return r.arrayBuffer().then(function(data){var m=/^bytes=(\\d*)-(\\d*)$/.exec(range);if(!m)return new Response(data,{status:200,headers:r.headers});var start=m[1]?Number(m[1]):Math.max(0,data.byteLength-Number(m[2])),end=m[1]?(m[2]?Math.min(Number(m[2]),data.byteLength-1):data.byteLength-1):data.byteLength-1;if(start>end||start>=data.byteLength)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+data.byteLength}});var headers=new Headers(r.headers);headers.set('Content-Range','bytes '+start+'-'+end+'/'+data.byteLength);headers.set('Content-Length',String(end-start+1));headers.set('Accept-Ranges','bytes');return new Response(data.slice(start,end+1),{status:206,headers:headers});});});}));
});
""".replace('VERSION',version).replace('PATHS',json.dumps(paths,ensure_ascii=False))
(root/'sw.js').write_text(source,encoding='utf-8')
(root/'pwa-release.json').write_text(json.dumps(dict(version=version,files=len(paths),bytes=sum(x.stat().st_size for x in files)),indent=2),encoding='utf-8')
print('PWA release',version,len(files),'files',sum(x.stat().st_size for x in files),'bytes')
